// === EXTRAIR chatId, text e sessionId DO EVENTO OPENWA ===
// O OpenWA (ingress) entrega o evento de mensagem no corpo do webhook.
// Suporta tanto o formato { body: { data: {...} } } quanto payload plano.

const body = $json.body || $json;
const data = body.data || body;

// chatId (identificador da conversa WhatsApp)
const chatId = data.chatId || data.from || body.chatId || '';

// texto da mensagem
const text = data.body || data.text || body.text || '';

// sessionId: prioriza o payload; cai para variavel de ambiente configuravel
const sessionId = data.sessionId || body.sessionId || $env.OPENWA_SESSION_ID || 'default';

if (!chatId || !text) {
  // Sem chatId/text nao ha o que processar; encaminha um marcador de skip.
  return {
    json: {
      route: 'skip',
      reason: 'Payload sem chatId ou text',
      chatId,
      sessionId,
    },
  };
}

return {
  json: {
    chatId,
    text,
    sessionId,
    timestamp: new Date().toISOString(),
  },
};

// === PREPARAR REPLY PARA REENVIO ===
// A rota /intake/messages devolve o lead persistido. A resposta conversacional
// para o cliente pode vir em `reply` (fluxo do Plan 02) ou, na ausencia dela,
// usa-se um ack padrao. Recupera chatId/sessionId do node anterior.

const apiResponse = $json || {};
const prev = $('1. Extrair chatId + text').first().json;

const chatId = prev.chatId;
const sessionId = prev.sessionId;

// A `reply` conversacional, quando o backend a fornecer.
let reply = apiResponse.reply;

// Fallback: enquanto o fluxo conversacional (Plan 02) nao popular `reply`,
// confirma o recebimento ao cliente.
if (!reply || String(reply).trim() === '') {
  reply = 'Recebemos sua mensagem e ja iniciamos seu atendimento. Em breve retornamos.';
}

return {
  json: {
    chatId,
    sessionId,
    text: reply,
  },
};
